import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Queue;

class Solution {
    public int snakesAndLadders(int[][] board) {
        int size = board.length;
        int last = size * size;
        List<List<Integer>> graph = new ArrayList<>();
        for (int square = 0; square <= last; square++) graph.add(new ArrayList<>());
        for (int square = 1; square < last; square++) {
            for (int landing = square + 1; landing <= Math.min(square + 6, last); landing++) {
                int[] cell = cellFor(landing, size);
                int destination = board[cell[0]][cell[1]] == -1 ? landing : board[cell[0]][cell[1]];
                graph.get(square).add(destination);
            }
        }
        int[] distance = new int[last + 1];
        Arrays.fill(distance, -1);
        Queue<Integer> queue = new ArrayDeque<>();
        distance[1] = 0; queue.offer(1);
        while (!queue.isEmpty()) {
            int square = queue.poll();
            if (square == last) return distance[square];
            for (int next : graph.get(square)) if (distance[next] == -1) { distance[next] = distance[square] + 1; queue.offer(next); }
        }
        return -1;
    }
    private int[] cellFor(int square, int size) {
        int offset = square - 1;
        int rowFromBottom = offset / size;
        int colOffset = offset % size;
        int col = rowFromBottom % 2 == 0 ? colOffset : size - 1 - colOffset;
        return new int[] {size - 1 - rowFromBottom, col};
    }
}

