import java.util.Queue;

class Solution {
    public int snakesAndLadders(int[][] board) {
        int size = board.length;
        int last = size * size;
        int[] distance = new int[last + 1];
        Arrays.fill(distance, -1);
        Queue<Integer> queue = new ArrayDeque<>();
        distance[1] = 0; queue.offer(1);
        while (!queue.isEmpty()) {
            int square = queue.poll();
            if (square == last) return distance[square];
            for (int landing = square + 1; landing <= Math.min(square + 6, last); landing++) {
                int offset = landing - 1;
                int rowFromBottom = offset / size;
                int colOffset = offset % size;
                int col = rowFromBottom % 2 == 0 ? colOffset : size - 1 - colOffset;
                int row = size - 1 - rowFromBottom;
                int next = board[row][col] == -1 ? landing : board[row][col];
                if (distance[next] == -1) { distance[next] = distance[square] + 1; queue.offer(next); }
            }
        }
        return -1;
    }
